package dev.mineagent.runtime.core.interaction;
import com.fasterxml.jackson.databind.*;import java.util.*;
public record InteractionRuleSpec(String name,String dimension,List<Integer> position,String entityId,Set<String> events,String decision,String keyItem,String keyInstance,String keyPart,Set<UUID> allow,List<Map<String,String>> deniedActions,List<Map<String,String>> allowedActions,String source){
 public static InteractionRuleSpec parse(String source){try{if(source==null||source.length()>12000)throw new IllegalArgumentException("INTERACTION_RULE_SIZE");var j=new ObjectMapper().readTree(source);keys(j,"name","dimension","position","entity_id","events","decision","key_item","key_instance","key_part","allow_players","on_denied","on_allowed");String name=j.path("name").asText("交互规则"),dim=j.path("dimension").asText("minecraft:overworld");if(name.length()>80||!dim.matches("[a-z0-9_.-]+:[a-z0-9_/.-]+"))throw new IllegalArgumentException("INTERACTION_RULE_ID");var position=new ArrayList<Integer>();if(j.has("position")){if(!j.get("position").isArray()||j.get("position").size()!=3)throw new IllegalArgumentException("INTERACTION_RULE_POSITION");for(var n:j.get("position")){if(!n.isIntegralNumber()||!n.canConvertToInt()||Math.abs((long)n.intValue())>30000000)throw new IllegalArgumentException("INTERACTION_RULE_POSITION");position.add(n.intValue());}}String entity=j.path("entity_id").asText("");if(!entity.isEmpty())UUID.fromString(entity);if(position.isEmpty()==entity.isEmpty())throw new IllegalArgumentException("INTERACTION_RULE_ONE_TARGET");var events=new HashSet<String>();if(!j.path("events").isArray())throw new IllegalArgumentException("INTERACTION_RULE_EVENTS");for(var n:j.get("events")){String e=n.asText();if(!Set.of("block_use","block_break","block_place","entity_use","entity_attack").contains(e)||position.isEmpty()!=e.startsWith("entity"))throw new IllegalArgumentException("INTERACTION_RULE_EVENTS");events.add(e);}if(events.isEmpty())throw new IllegalArgumentException("INTERACTION_RULE_EVENTS");String decision=j.path("decision").asText("cancel");if(!Set.of("cancel","continue").contains(decision))throw new IllegalArgumentException("INTERACTION_RULE_DECISION");String item=j.path("key_item").asText(""),instance=j.path("key_instance").asText(""),part=j.path("key_part").asText("");if(!item.isEmpty()&&!item.matches("[a-z0-9_.-]+:[a-z0-9_/.-]+"))throw new IllegalArgumentException("INTERACTION_RULE_KEY");if(!instance.isEmpty())UUID.fromString(instance);if(instance.isEmpty()!=part.isEmpty()||part.length()>64)throw new IllegalArgumentException("INTERACTION_RULE_KEY");var allow=new HashSet<UUID>();if(j.has("allow_players")){if(!j.get("allow_players").isArray()||j.get("allow_players").size()>128)throw new IllegalArgumentException("INTERACTION_RULE_PLAYERS");for(var n:j.get("allow_players"))allow.add(UUID.fromString(n.asText()));}return new InteractionRuleSpec(name,dim,List.copyOf(position),entity,Set.copyOf(events),decision,item,instance,part,Set.copyOf(allow),actions(j.path("on_denied")),actions(j.path("on_allowed")),new ObjectMapper().writeValueAsString(j));}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("INTERACTION_RULE_INVALID",e);}}
 private static void keys(JsonNode n,String... keys){if(!n.isObject()||!Set.of(keys).containsAll(n.properties().stream().map(Map.Entry::getKey).toList()))throw new IllegalArgumentException("INTERACTION_RULE_FIELDS");}
 private static List<Map<String,String>> actions(JsonNode n){if(n.isMissingNode())return List.of();if(!n.isArray()||n.size()>8)throw new IllegalArgumentException("INTERACTION_RULE_ACTIONS");var out=new ArrayList<Map<String,String>>();for(var a:n){keys(a,"type","value");String type=a.path("type").asText(),value=a.path("value").asText();if(!Set.of("message","sound","command").contains(type)||!a.path("value").isTextual()||value.isBlank()||value.length()>512)throw new IllegalArgumentException("INTERACTION_RULE_ACTION");out.add(Map.of("type",type,"value",value));}return List.copyOf(out);}
}
